public class PrivateFieldPokerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object read(Object target, String name) {
        try {
            return PrivateFieldPoker.readField(target, name);
        } catch (Throwable t) {
            return t.getClass().getSimpleName() + ": " + t.getMessage();
        }
    }

    static String write(Object target, String name, Object value) {
        try {
            PrivateFieldPoker.writeField(target, name, value);
            return "ok";
        } catch (Throwable t) {
            return t.getClass().getSimpleName() + ": " + t.getMessage();
        }
    }

    public static void main(String[] args) {
        SecretVault vault = new SecretVault();

        check("read a private String field", "swordfish", read(vault, "secret"));
        check("read a private int field, boxed", 0, read(vault, "attempts"));
        check("writing the String field", "ok", write(vault, "secret", "opensesame"));
        check("the object really changed", "opensesame/0", vault.status());
        check("writing the int field", "ok", write(vault, "attempts", 3));
        check("reading back what was written", 3, read(vault, "attempts"));
        check("both changes are visible", "opensesame/3", vault.status());
        check("an unknown field name", "NoSuchFieldException: nope", read(vault, "nope"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

